// Box art for Panel Pop (meta/box_art.png), drawn by the game's own runtime like scripts/make-cart-art.mjs, with a
// layout of its own (panels, the cast and the title) that the generic cover does not make. The screenshot and logo still come from make-cart-art.mjs.
// usage: node scripts/make-panel-pop-art.mjs        (needs build/gs and carts/panel-pop generated by make-panel-pop.mjs)
import { copyFileSync, mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { png, decodeBmp } from "./png.mjs";
import { writePictureCart } from "./picture-cart.mjs";

const dir = "carts/panel-pop";
const tmp = mkdtempSync(join(tmpdir(), "gs-box-"));
mkdirSync(join(tmp, "sprites"));
const sprites = ["spr_panels", "spr_char_pip", "spr_doc", "spr_char_bloop", "spr_char_ember", "spr_bigvirus", "spr_pills"];
for (const s of sprites) copyFileSync(join(dir, "sprites", s + ".png"), join(tmp, "sprites", s + ".png"));
const pal = JSON.parse(readFileSync(join("engine", "consoles", "dot.json"), "utf8")).palette.colors;
const c = (i) => [parseInt(pal[i].slice(1, 3), 16), parseInt(pal[i].slice(3, 5), 16), parseInt(pal[i].slice(5, 7), 16)].join(", ");
const body = `
  gs.clear(${c(24)})
  for y = 0, H, 32 do for x = 0, W, 32 do if ((x + y) / 32) % 2 == 0 then gs.rect(x, y, 32, 32, ${c(25)}) end end end
  gs.rect(0, 0, W, 6, ${c(6)}); gs.rect(0, 6, W, 6, ${c(10)}); gs.rect(0, 12, W, 6, ${c(14)})
  local function shadowed(s, y, sc, col)
    local x = math.floor((W - #s * 8 * sc) / 2)
    gs.print(s, x + sc, y + sc, 0, 0, 0, 255, sc)
    gs.print(s, x, y, col[1], col[2], col[3], 255, sc)
  end
  shadowed("PANEL", 34, 6, {${c(14)}})
  shadowed("POP", 88, 6, {${c(6)}})
  shadowed("& DOC CAPSULE", 146, 2, {255, 255, 255})
  local panels, pills, doc, pip, bloop, ember, vir = img("spr_panels"), img("spr_pills"), img("spr_doc"), img("spr_char_pip"), img("spr_char_bloop"), img("spr_char_ember"), img("spr_bigvirus")
  for i = 0, 5 do gs.tile(panels, i * 6 * 16, 0, 16, 16, 24 + i * 32, 184, 2) end
  gs.tile(doc, 0, 0, 32, 32, 12, 238, 2)
  gs.tile(pip, 0, 0, 32, 32, 88, 238, 2)
  gs.tile(vir, 0, 0, 32, 32, 164, 238, 2)
  gs.print("GAMESTUDIO", 80, 308, 255, 255, 255, 120, 1)
`;
writePictureCart(tmp, 240, 320, body, `local function img(n) return gs.image("sprites/" .. n .. ".png") end`);
const bmp = join(tmp, "frame.bmp");
const r = spawnSync("build/gs", [tmp], { encoding: "utf8", env: { ...process.env, GS_SAVE_DIR: mkdtempSync(join(tmpdir(), "gs-save-")), SDL_VIDEODRIVER: "dummy", SDL_AUDIODRIVER: "dummy", GS_MAX_FRAMES: "3", GS_DUMP_FRAME: bmp } });
if (r.status !== 0) { console.error(r.stdout, r.stderr); process.exit(1); }
const f = decodeBmp(readFileSync(bmp));
writeFileSync(join(dir, "meta/box_art.png"), png(f.width, f.height, f.data));
console.log("wrote carts/panel-pop/meta/box_art.png");
